1. using System.Text.Json.Nodes;
2. using System.Text.Json.Serialization;
3. using SkillValidator.Shared;
4. 
5. namespace SkillValidator.Evaluate;
6. 
7. // --- Failure classification ---
8. 
9. [JsonConverter(typeof(JsonStringEnumConverter<FailureKind>))]
10. public enum FailureKind
11. {
12.     [JsonStringEnumMemberName("no_scenarios")]
13.     NoScenarios,
14. 
15.     [JsonStringEnumMemberName("completion_regression")]
16.     CompletionRegression,
17. 
18.     [JsonStringEnumMemberName("threshold")]
19.     Threshold,
20. 
21.     [JsonStringEnumMemberName("spec_conformance_failure")]
22.     SpecConformanceFailure,
23. 
24.     [JsonStringEnumMemberName("skill_not_activated")]
25.     SkillNotActivated,
26. 
27.     [JsonStringEnumMemberName("noise_degradation")]
28.     NoiseDegradation,
29. }
30. 
31. // --- Assertion types ---
32. 
33. public enum AssertionType
34. {
35.     FileExists,
36.     FileNotExists,
37.     FileContains,
38.     FileNotContains,
39.     OutputContains,
40.     OutputNotContains,
41.     OutputMatches,
42.     OutputNotMatches,
43.     ExitSuccess,
44.     RunCommandAndAssert,
45.     ExpectTools,
46.     RejectTools,
47.     MaxTurns,
48.     MaxTokens,
49. }
50. 
51. public sealed record CommandAssertionArgs(
52.     string CommandToRun,
53.     string? CommandArguments = null,
54.     int? ExpectedExitCode = null,
55.     string? ExpectedStdOutContains = null,
56.     string? ExpectedStdErrorContains = null,
57.     string? ExpectedStdOutMatches = null,
58.     string? ExpectedStdErrorMatches = null,
59.     int? Timeout = null);
60. 
61. public sealed record Assertion(
62.     AssertionType Type,
63.     string? Path = null,
64.     string? Value = null,
65.     string? Pattern = null,
66.     CommandAssertionArgs? CommandArgs = null);
67. 
68. public sealed record AssertionResult(
69.     Assertion Assertion,
70.     bool Passed,
71.     string Message);
72. 
73. // --- Setup ---
74. 
75. public sealed record SetupFile(
76.     string Path,
77.     string? Source = null,
78.     string? Content = null);
79. 
80. public sealed record SetupConfig(
81.     bool CopyTestFiles = false,
82.     IReadOnlyList<SetupFile>? Files = null,
83.     IReadOnlyList<string>? Commands = null,
84.     IReadOnlyList<string>? AdditionalRequiredSkills = null,
85.     IReadOnlyList<string>? AdditionalRequiredAgents = null);
86. 
87. // --- Scenario ---
88. 
89. public sealed record EvalScenario(
90.     string Name,
91.     string Prompt,
92.     SetupConfig? Setup = null,
93.     IReadOnlyList<Assertion>? Assertions = null,
94.     IReadOnlyList<string>? Rubric = null,
95.     int Timeout = EvalSchema.DefaultScenarioTimeoutSeconds,
96.     IReadOnlyList<string>? ExpectTools = null,
97.     IReadOnlyList<string>? RejectTools = null,
98.     int? MaxTurns = null,
99.     int? MaxTokens = null,
100.     bool ExpectActivation = true);
101. 
102. public sealed record EvalConfig(
103.     IReadOnlyList<EvalScenario> Scenarios,
104.     int? MaxParallelScenarios = null,
105.     int? MaxParallelRuns = null);
106. 
107. /// <summary>
108. /// Extends SkillInfo with evaluation-specific data (eval.yaml config, MCP servers).
109. /// Used only by the eval command and its supporting services.
110. /// </summary>
111. public sealed record EvalSkillInfo(
112.     SkillInfo Skill,
113.     string? EvalPath,
114.     EvalConfig? EvalConfig,
115.     IReadOnlyDictionary<string, MCPServerDef>? McpServers = null);
116. 
117. /// <summary>
118. /// Unified eval target — either a skill or an agent.
119. /// Most of the evaluation pipeline operates on this generically.
120. /// </summary>
121. public enum EvalTargetKind { Skill, Agent }
122. 
123. public sealed record EvalTargetInfo(
124.     string Name,
125.     string Path,
126.     EvalTargetKind Kind,
127.     SkillInfo? Skill,
128.     AgentInfo? Agent,
129.     string? EvalPath,
130.     EvalConfig? EvalConfig,
131.     string? PluginRoot,
132.     IReadOnlyDictionary<string, MCPServerDef>? McpServers);
133. 
134. // --- Agent events ---
135. 
136. public sealed record AgentEvent(
137.     string Type,
138.     long Timestamp,
139.     Dictionary<string, JsonNode?> Data);
140. 
141. // --- Judge results ---
142. 
143. public sealed record RubricScore(
144.     string Criterion,
145.     double Score,
146.     string Reasoning);
147. 
148. public sealed record JudgeResult(
149.     IReadOnlyList<RubricScore> RubricScores,
150.     double OverallScore,
151.     string OverallReasoning);
152. 
153. /// <summary>Lightweight token counter returned by judge helpers.</summary>
154. public sealed record TokenUsage(int InputTokens, int OutputTokens, int CacheReadTokens, int CacheWriteTokens)
155. {
156.     public static TokenUsage Zero { get; } = new(0, 0, 0, 0);
157. 
158.     public static TokenUsage operator +(TokenUsage a, TokenUsage b) =>
159.         new(a.InputTokens + b.InputTokens,
160.             a.OutputTokens + b.OutputTokens,
161.             a.CacheReadTokens + b.CacheReadTokens,
162.             a.CacheWriteTokens + b.CacheWriteTokens);
163. }
164. 
165. // --- Run metrics ---
166. 
167. public sealed class RunMetrics
168. {
169.     public int TokenEstimate { get; set; }
170.     public int InputTokens { get; set; }
171.     public int OutputTokens { get; set; }
172.     public int CacheReadTokens { get; set; }
173.     public int CacheWriteTokens { get; set; }
174.     public int JudgeInputTokens { get; set; }
175.     public int JudgeOutputTokens { get; set; }
176.     public int JudgeCacheReadTokens { get; set; }
177.     public int JudgeCacheWriteTokens { get; set; }
178.     public int ToolCallCount { get; set; }
179.     public Dictionary<string, int> ToolCallBreakdown { get; set; } = new();
180.     public int TurnCount { get; set; }
181.     public long WallTimeMs { get; set; }
182.     public int ErrorCount { get; set; }
183.     public bool TimedOut { get; set; }
184.     public List<AssertionResult> AssertionResults { get; set; } = [];
185.     public bool TaskCompleted { get; set; }
186.     public string AgentOutput { get; set; } = "";
187.     public List<AgentEvent> Events { get; set; } = [];
188.     public string WorkDir { get; set; } = "";
189. 
190.     /// <summary>
191.     /// Creates a per-run copy.  Scalar fields are copied by value and the mutable
192.     /// collections are re-wrapped in fresh instances so mutating the clone (e.g.
193.     /// accumulating judge tokens) never affects the source.  This is essential when a
194.     /// cached baseline is reused concurrently across parallel target evaluations: each
195.     /// evaluation works on its own copy instead of sharing one mutable instance.
196.     /// </summary>
197.     public RunMetrics Clone() => new()
198.     {
199.         TokenEstimate = TokenEstimate,
200.         InputTokens = InputTokens,
201.         OutputTokens = OutputTokens,
202.         CacheReadTokens = CacheReadTokens,
203.         CacheWriteTokens = CacheWriteTokens,
204.         JudgeInputTokens = JudgeInputTokens,
205.         JudgeOutputTokens = JudgeOutputTokens,
206.         JudgeCacheReadTokens = JudgeCacheReadTokens,
207.         JudgeCacheWriteTokens = JudgeCacheWriteTokens,
208.         ToolCallCount = ToolCallCount,
209.         ToolCallBreakdown = new Dictionary<string, int>(ToolCallBreakdown),
210.         TurnCount = TurnCount,
211.         WallTimeMs = WallTimeMs,
212.         ErrorCount = ErrorCount,
213.         TimedOut = TimedOut,
214.         AssertionResults = [.. AssertionResults],
215.         TaskCompleted = TaskCompleted,
216.         AgentOutput = AgentOutput,
217.         Events = [.. Events],
218.         WorkDir = WorkDir,
219.     };
220. }
221. 
222. public sealed record RunResult(
223.     RunMetrics Metrics,
224.     JudgeResult JudgeResult);
225. 
226. // --- Pairwise judging ---
227. 
228. public enum PairwiseMagnitude
229. {
230.     MuchBetter,
231.     SlightlyBetter,
232.     Equal,
233.     SlightlyWorse,
234.     MuchWorse,
235. }
236. 
237. public sealed record PairwiseRubricResult(
238.     string Criterion,
239.     string Winner, // "baseline" | "skill" | "tie"
240.     PairwiseMagnitude Magnitude,
241.     string Reasoning);
242. 
243. public sealed record PairwiseJudgeResult(
244.     IReadOnlyList<PairwiseRubricResult> RubricResults,
245.     string OverallWinner, // "baseline" | "skill" | "tie"
246.     PairwiseMagnitude OverallMagnitude,
247.     string OverallReasoning,
248.     bool PositionSwapConsistent);
249. 
250. public static class PairwiseMagnitudeScores
251. {
252.     public static double GetScore(PairwiseMagnitude magnitude) => magnitude switch
253.     {
254.         PairwiseMagnitude.MuchBetter => 1.0,
255.         PairwiseMagnitude.SlightlyBetter => 0.4,
256.         PairwiseMagnitude.Equal => 0.0,
257.         PairwiseMagnitude.SlightlyWorse => -0.4,
258.         PairwiseMagnitude.MuchWorse => -1.0,
259.         _ => 0.0,
260.     };
261. }
262. 
263. public enum JudgeMode
264. {
265.     Pairwise,
266.     Independent,
267.     Both,
268. }
269. 
270. // --- Skill activation ---
271. 
272. public sealed record SkillActivationInfo(
273.     bool Activated,
274.     IReadOnlyList<string> DetectedSkills,
275.     IReadOnlyList<string> ExtraTools,
276.     int SkillEventCount);
277. 
278. // --- Subagent (custom agent) activation ---
279. 
280. public sealed record SubagentActivationInfo(
281.     IReadOnlyList<string> InvokedAgents,
282.     int SubagentEventCount);
283. 
284. // --- Comparison ---
285. 
286. public sealed record MetricBreakdown(
287.     double TokenReduction,
288.     double ToolCallReduction,
289.     double TaskCompletionImprovement,
290.     double TimeReduction,
291.     double QualityImprovement,
292.     double OverallJudgmentImprovement,
293.     double ErrorReduction);
294. 
295. public sealed record ConfidenceInterval(
296.     double Low,
297.     double High,
298.     double Level);
299. 
300. public sealed class ScenarioComparison
301. {
302.     public required string ScenarioName { get; init; }
303.     public required RunResult Baseline { get; init; }
304.     public RunResult SkilledIsolated { get; init; } = null!;
305.     public RunResult? SkilledPlugin { get; init; }
306.     public required double ImprovementScore { get; init; }
307.     public double IsolatedImprovementScore { get; init; }
308.     public double PluginImprovementScore { get; init; }
309.     public required MetricBreakdown Breakdown { get; init; }
310.     public MetricBreakdown? IsolatedBreakdown { get; init; }
311.     public MetricBreakdown? PluginBreakdown { get; init; }
312.     public PairwiseJudgeResult? PairwiseResult { get; init; }
313.     public IReadOnlyList<double>? PerRunScores { get; set; }
314.     /// <summary>True when the coefficient of variation across runs exceeds the high-variance threshold.</summary>
315.     public bool HighVariance { get; set; }
316.     /// <summary>Coefficient of variation across per-run scores. Null when fewer than 2 runs.</summary>
317.     public double? VarianceCV { get; set; }
318.     public SkillActivationInfo? SkillActivationIsolated { get; set; }
319.     public SkillActivationInfo? SkillActivationPlugin { get; set; }
320.     public SubagentActivationInfo? SubagentActivationIsolated { get; set; }
321.     public SubagentActivationInfo? SubagentActivationPlugin { get; set; }
322.     public bool TimedOut { get; set; }
323.     /// <summary>The scenario timeout in seconds, if known (e.g., from eval.yaml or persisted session data).</summary>
324.     public int? TimeoutSeconds { get; set; }
325.     /// <summary>When false, non-activation is expected (negative test) and should not flag the verdict.</summary>
326.     public bool ExpectActivation { get; set; } = true;
327.     /// <summary>Number of individual runs that failed with exceptions and were excluded from aggregation.</summary>
328.     public int FailedRunCount { get; set; }
329.     /// <summary>Non-null when the entire scenario failed with an execution error (not a timeout).</summary>
330.     public string? ExecutionError { get; set; }
331. 
332.     // Backward-compatible aliases for JSON deserialization of older results files.
333.     [JsonPropertyName("withSkill")]
334.     public RunResult WithSkill { get => SkilledIsolated; init => SkilledIsolated = value; }
335.     [JsonPropertyName("skillActivation")]
336.     public SkillActivationInfo? SkillActivation { get => SkillActivationIsolated; init => SkillActivationIsolated = value; }
337. }
338. 
339. // --- Verdict ---
340. 
341. public sealed class SkillVerdict
342. {
343.     public required string SkillName { get; init; }
344.     public required string SkillPath { get; init; }
345.     public required bool Passed { get; set; }
346.     public required IReadOnlyList<ScenarioComparison> Scenarios { get; init; }
347.     public required double OverallImprovementScore { get; init; }
348.     public double? NormalizedGain { get; init; }
349.     public ConfidenceInterval? ConfidenceInterval { get; init; }
350.     public bool? IsSignificant { get; init; }
351.     public double? IsolatedScore { get; set; }
352.     public double? PluginScore { get; set; }
353.     public required string Reason { get; set; }
354.     /// <summary>Categorizes why the verdict failed, if it did.</summary>
355.     public FailureKind? FailureKind { get; set; }
356.     public bool SkillNotActivated { get; set; }
357.     public OverfittingResult? OverfittingResult { get; set; }
358.     public NoiseTestResult? NoiseTestResult { get; set; }
359. }
360. 
361. // --- Overfitting assessment ---
362. 
363. [JsonConverter(typeof(JsonStringEnumConverter<OverfittingSeverity>))]
364. public enum OverfittingSeverity
365. {
366.     Low,
367.     Moderate,
368.     High,
369. }
370. 
371. public sealed record RubricOverfitAssessment(
372.     string Scenario,
373.     string Criterion,
374.     string Classification,      // "outcome" | "technique" | "vocabulary"
375.     double Confidence,
376.     string Reasoning);
377. 
378. public sealed record AssertionOverfitAssessment(
379.     string Scenario,
380.     string AssertionSummary,
381.     string Classification,      // "broad" | "narrow"
382.     double Confidence,
383.     string Reasoning);
384. 
385. public sealed record PromptOverfitAssessment(
386.     string Scenario,
387.     string Issue,               // e.g. "explicit_skill_reference" | "skill_instruction"
388.     double Confidence,
389.     string Reasoning);
390. 
391. public sealed record OverfittingResult(
392.     double Score,               // [0, 1]
393.     OverfittingSeverity Severity,
394.     IReadOnlyList<RubricOverfitAssessment> RubricAssessments,
395.     IReadOnlyList<AssertionOverfitAssessment> AssertionAssessments,
396.     IReadOnlyList<PromptOverfitAssessment> PromptAssessments,
397.     IReadOnlyList<string> CrossScenarioIssues,
398.     string OverallReasoning);
399. 
400. public sealed record OverfittingJudgeOptions(
401.     string Model,
402.     bool Verbose,
403.     int Timeout,
404.     string WorkDir);
405. 
406. // --- Multi-skill noise test ---
407. 
408. public sealed record NoiseScenarioResult(
409.     string ScenarioName,
410.     RunResult WithSkillOnly,
411.     RunResult WithAllSkills,
412.     double DegradationScore,
413.     MetricBreakdown Breakdown,
414.     SkillActivationInfo? SkillActivation,
415.     int TotalSkillsLoaded);
416. 
417. public sealed record NoiseTestResult(
418.     IReadOnlyList<NoiseScenarioResult> Scenarios,
419.     double OverallDegradation,
420.     bool Passed,
421.     string Reason,
422.     int TotalSkillsLoaded);
423. 
424. // --- Eval config ---
425. 
426. public sealed record ReporterSpec(ReporterType Type);
427. 
428. public enum ReporterType
429. {
430.     Console,
431.     Json,
432.     Junit,
433.     Markdown,
434. }
435. 
436. public sealed record ValidatorConfig
437. {
438.     public double MinImprovement { get; init; } = 0.1;
439.     public bool RequireCompletion { get; init; } = true;
440.     public bool Verbose { get; init; }
441.     public string Model { get; init; } = "claude-opus-4.6";
442.     public string JudgeModel { get; init; } = "claude-opus-4.6";
443.     public JudgeMode JudgeMode { get; init; } = JudgeMode.Pairwise;
444.     public int Runs { get; init; } = 5;
445.     public int ParallelSkills { get; init; } = 1;
446.     public int ParallelScenarios { get; init; } = 1;
447.     public int ParallelRuns { get; init; } = 1;
448.     public int JudgeTimeout { get; init; } = 300_000;
449.     public double ConfidenceLevel { get; init; } = 0.95;
450.     public IReadOnlyList<ReporterSpec> Reporters { get; init; } = [];
451.     public IReadOnlyList<string> SkillPaths { get; init; } = [];
452.     public bool VerdictWarnOnly { get; init; }
453.     public string? ResultsDir { get; init; }
454.     public string? TestsDir { get; init; }
455.     public bool OverfittingCheck { get; init; } = true;
456.     public bool OverfittingFix { get; init; }
457.     public bool KeepSessions { get; init; }
458.     public string? NoiseSkillsDir { get; init; }
459.     public double NoiseDegradationLimit { get; init; } = 0.2;
460.     public double NoiseMaxScenarioDegradation { get; init; } = 0.4;
461. 
462.     /// <summary>When set, persist each scenario's averaged baseline to this file after the run.</summary>
463.     public string? BaselineOut { get; init; }
464. 
465.     /// <summary>When set, reuse the precomputed baseline from this file instead of re-running the baseline arm.</summary>
466.     public string? BaselineFrom { get; init; }
467. 
468.     /// <summary>
469.     /// When set, run the requested agent arms and persist sessions/metrics but skip all judging.
470.     /// Judging is deferred to a later <c>rejudge</c>/<c>judge</c> step. Implies session persistence
471.     /// and does not require a baseline.
472.     /// </summary>
473.     public bool NoJudge { get; init; }
474. }
475. 
476. public static class DefaultWeights
477. {
478.     public static readonly IReadOnlyDictionary<string, double> Values = new Dictionary<string, double>
479.     {
480.         ["TokenReduction"] = 0.05,
481.         ["ToolCallReduction"] = 0.025,
482.         ["TaskCompletionImprovement"] = 0.15,
483.         ["TimeReduction"] = 0.025,
484.         ["QualityImprovement"] = 0.40,
485.         ["OverallJudgmentImprovement"] = 0.30,
486.         ["ErrorReduction"] = 0.05,
487.     };
488. }
489. 
490. // --- JSON transport types ---
491. 
492. internal sealed class ConsolidateData
493. {
494.     public string? Model { get; set; }
495.     public string? JudgeModel { get; set; }
496.     public List<SkillVerdict>? Verdicts { get; set; }
497. }
498. 
499. internal sealed class ResultsOutput
500. {
501.     public required string Model { get; init; }
502.     public required string JudgeModel { get; init; }
503.     public required string Timestamp { get; init; }
504.     public required IReadOnlyList<SkillVerdict> Verdicts { get; init; }
505. }
506.

